import { exitCode } from './coverage.js';
import { scan } from './scan.js';
import { json, markdown } from './report.js';
let root=process.cwd();let format='json';let gate=false;
try {
  const args=process.argv.slice(2).filter(a=>{if(a==='--fail-on-findings'){gate=true;return false;}return true;});
  for(let i=0;i<args.length;i+=2){const key=args[i],value=args[i+1];if(!value||value.startsWith('--'))throw new Error('Missing option value');if(key==='--root')root=value;else if(key==='--format'&&['json','markdown'].includes(value))format=value;else throw new Error('Unknown option or format');}
  const r=await scan(root);process.stdout.write(format==='markdown'?markdown(r):json(r));process.exitCode=exitCode(r.complete,r.findings.filter(f=>!['INFORMATIONAL','INTENTIONAL_LTR'].includes(f.category)).length,gate);
}catch(e){console.error(e instanceof Error?e.message:'Scan failed');process.exitCode=2;}

